import { ref, reactive } from 'vue';
export default {
  props: {
    loading: Boolean
  },
  emits: ['register'],
  setup(props, {
    emit
  }) {
    const username = ref('');
    const email = ref('');
    const password = ref('');
    const password2 = ref('');
    const errors = reactive({
      username: [],
      email: [],
      password: [],
      password2: [],
      general: null
    });
    const clearError = field => {
      errors[field] = [];
      errors.general = null;
    };
    const submitForm = () => {
      if (password.value !== password2.value) {
        errors.password2 = ['Passwords do not match'];
        return;
      }
      emit('register', {
        username: username.value,
        email: email.value,
        password: password.value,
        password2: password2.value
      });
    };
    const setErrors = newErrors => {
      Object.keys(errors).forEach(key => {
        errors[key] = [];
      });
      errors.general = null;
      if (typeof newErrors === 'string') {
        errors.general = newErrors;
      } else if (typeof newErrors === 'object' && newErrors !== null) {
        Object.keys(newErrors).forEach(field => {
          if (field in errors) {
            errors[field] = Array.isArray(newErrors[field]) ? newErrors[field] : [newErrors[field]];
          } else {
            errors.general = newErrors[field];
          }
        });
      }
    };
    return {
      username,
      email,
      password,
      password2,
      errors,
      submitForm,
      clearError,
      setErrors
    };
  }
};
